"""Build a standalone OFFLINE mobile portal. Not connected to Streamlit/SQLite or live stock."""
from __future__ import annotations
import json
from pathlib import Path
import sourcing
import raffles

ROOT=Path(__file__).resolve().parent

def js_json(obj):
    return json.dumps(obj,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')


def build_html():
    sources=[dict(id=s.id,name=s.name,group=s.group,domain=s.domain,site=s.site,
                  strategy=s.strategy,local=s.local,warning=s.warning) for s in sourcing.SOURCES]
    raff=[dict(id=r.id,brand=r.brand,title=r.title,category=r.category,method=r.method,
               url=r.url,requirements=r.requirements,deadline=r.known_deadline,
               state=r.state,note=r.note,source=r.source_url) for r in raffles.RAFFLES]
    source_json=js_json(sources)
    raffle_json=js_json(raff)
    trackers_json=js_json(raffles.TRACKERS)
    page=r'''<!doctype html><html lang="fr"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>PokéRadar v0.4 • Portail mobile</title>
<style>
:root{color-scheme:dark;--bg:#080e1c;--surface:#141e30;--surface2:#19273d;--line:#29384f;--txt:#f3f7ff;--muted:#96acc8;--accent:#69c9ee;--gold:#fbd276;--green:#88dbc0;--red:#feb0a9;font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}
*{box-sizing:border-box}body{background:radial-gradient(ellipse 80% 600px at 10% -20%,#204b6a 0,transparent 75%),var(--bg);color:var(--txt);margin:0;min-height:100vh}
main{width:min(1100px,95vw);margin:0 auto;padding:30px 0 80px}h1{font-size:clamp(2.1rem,7vw,3.6rem);letter-spacing:-.065em;margin:7px 0 12px;line-height:1.08}h2{font-size:1.5rem;letter-spacing:-.03em;margin:0 0 12px}h3{font-size:1.04rem;margin:0}p{line-height:1.5}small,.muted{color:var(--muted)}.eyebrow{color:var(--accent);font-weight:750;letter-spacing:.16em;font-size:.74rem}
header.hero{padding:15px 0 12px}.hero p{color:var(--muted);max-width:710px}.nav{display:flex;gap:6px;overflow-x:auto;position:sticky;top:0;background:#080e1cfa;z-index:10;padding:12px 0;border-bottom:1px solid var(--line);scrollbar-width:thin}.nav button{white-space:nowrap;border:1px solid transparent;padding:11px 13px;background:transparent;border-radius:12px;color:#aabbcf;cursor:pointer;font-size:.9rem}.nav button.active{color:#09212d;background:var(--accent);font-weight:750}
section.view{display:none;padding-top:27px}section.view.active{display:block}.notice{margin:17px 0;padding:14px 16px;border:1px solid #5e5031;border-radius:13px;background:#292518;color:#f4dbad;font-size:.93rem}.sub{color:var(--muted);margin-top:2px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:11px;margin:18px 0}.metric{border:1px solid var(--line);border-radius:14px;padding:16px;background:var(--surface)}.metric strong{display:block;font-size:1.8rem;font-variant-numeric:tabular-nums;margin-top:9px}.metric span{color:var(--muted);font-size:.82rem}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(255px,1fr));gap:13px;margin:15px 0}.card{background:var(--surface);border:1px solid var(--line);border-radius:17px;padding:17px;display:flex;flex-direction:column;gap:9px}.card p{margin:0;color:var(--muted);font-size:.88rem}.tag{font-size:.73rem;border:1px solid var(--line);padding:5px 8px;border-radius:9px;color:var(--muted);display:inline-block}.tag.green{color:var(--green);border-color:#31675d}.tag.red{color:var(--red);border-color:#6a4140}.tag.gold{color:var(--gold);border-color:#71613a}.top{display:flex;align-items:start;justify-content:space-between;gap:10px}.links{display:flex;flex-wrap:wrap;gap:7px;margin-top:auto}.btn,button.btn{display:inline-block;background:#0e7baf;color:#fff!important;text-decoration:none;border:0;padding:10px 12px;border-radius:11px;font-size:.86rem;font-weight:700;cursor:pointer}.btn.alt{background:#263851}.btn.danger{background:#693b3b}.input,select{background:#111c2d;color:#f3f7ff;border:1px solid #40536b;border-radius:11px;padding:12px;width:100%;font-size:1rem}.row{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:10px;margin:12px 0}.field{display:flex;flex-direction:column;gap:5px;color:#bcd0e5;font-size:.88rem}label{display:block}.filters{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0 8px}.filter{border:1px solid var(--line);border-radius:99px;color:var(--txt);background:var(--surface2);padding:8px 12px;cursor:pointer;font-size:.8rem}.filter.active{border-color:var(--accent);background:#214260}.empty{border:1px dashed #4a607a;border-radius:15px;padding:24px;color:var(--muted);text-align:center;margin:20px 0}.formCard{border:1px solid var(--line);background:var(--surface);padding:18px;border-radius:17px;margin:18px 0}.formCard button{margin-top:7px}.stat{font-size:1.3rem;font-weight:700}a{word-break:break-word}footer{color:#8398b3;font-size:.82rem;margin-top:48px;padding-top:20px;border-top:1px solid var(--line)}
</style></head><body><main>
<header class="hero"><div class="eyebrow">◉ POKÉRADAR • PORTAIL MOBILE 0.4</div><h1>Le radar Pokémon<br/>dans ta poche.</h1><p>Tirages au sort, achats, suivis de disponibilité et simulation de marge. Les informations saisies ici restent sur ce navigateur : ce portail ne se synchronise pas avec la version Mac.</p></header>
<div class="nav" role="tablist" aria-label="Navigation"><button class="active" data-view="overview" role="tab">🏠 Accueil</button><button data-view="draws" role="tab">🎟️ Tirages</button><button data-view="shopping" role="tab">🛒 Boutiques</button><button data-view="stock" role="tab">📍 Mes stocks</button><button data-view="calc" role="tab">🧮 Rentabilité</button></div>
<section id="overview" class="view active"><h2>Tableau de bord</h2><p class="sub">Version mobile autonome. Pour des scans HTML configurés, des courbes de marché et la base SQLite, ouvre l’application complète sur Mac.</p><div class="metrics"><div class="metric"><span>Sources d'achat</span><strong id="metricShop">27</strong></div><div class="metric"><span>Tirages & concours référencés</span><strong id="metricRaffles">7</strong></div><div class="metric"><span>Disponibilités que tu as saisies</span><strong id="metricStock">0</strong></div></div><div class="notice">Aucun prix ou stock Fnac/Amazon/Micromania n’est interrogé en direct dans ce fichier. « Disponible » est une observation manuelle et peut devenir obsolète.</div><div class="grid"><div class="card"><h3>🎟️ Tirages et invitations</h3><p>Fnac+, Micromania et Amazon : accéder aux formulaires et vérifier les dates.</p><button class="btn" data-go="draws">Voir les tirages</button></div><div class="card"><h3>📍 Suivi de stock</h3><p>Enregistre tes appels, les prix et les disponibilités vues en magasin, avec date.</p><button class="btn" data-go="stock">Mes observations</button></div><div class="card"><h3>🛒 Acheter au bon prix</h3><p>27 sites pour chercher chaque format Pokémon par nom ou code EAN.</p><button class="btn" data-go="shopping">Où acheter</button></div></div></section>
<section id="draws" class="view"><h2>Tirages au sort et invitations</h2><p class="sub">Liens historiques et pages à surveiller. La page officielle du commerçant fait foi.</p><div class="notice">Un tirage gagné ne garantit ni stock ni réservation. Les inscriptions Fnac+ du 6 novembre sont closes ; le lien Amazon permet de rechercher les produits, pas de confirmer une invitation.</div><div class="links" style="margin:14px 0"><a class="btn" href="https://animation.fnac.com/zn/pokemon-6nov" target="_blank" rel="noopener noreferrer">Fnac+ (ancien tirage)</a><a class="btn" href="https://www.micromania.fr/inscription-vente-reservee-bww83mkjeimn8jbp.html" target="_blank" rel="noopener noreferrer">Micromania (ancien tirage)</a><a class="btn" href="https://radarstock.fr/pokemon/tirages/" target="_blank" rel="noopener noreferrer">Nouvelles inscriptions</a></div><div class="filters" id="drawFilters"></div><div id="drawList" class="grid"></div><h3>Liens à surveiller et cartes d'adhérent</h3><div id="trackers" class="grid"></div></section>
<section id="shopping" class="view"><h2>Où acheter ?</h2><p class="sub">27 sources, liens directs ou recherches par enseigne. Pas de prix ni de stock en temps réel.</p><label class="field">Produit / EAN / édition<input class="input" id="productQuery" value="Pokémon JCC Règne Delta FR" type="search" autocomplete="off"/></label><div class="filters" id="shopFilters"></div><div id="shopList" class="grid"></div></section>
<section id="stock" class="view"><h2>Mes disponibilités</h2><p class="sub">Tu enregistres une observation par appel, retrait ou fiche consultée. Ces données sont stockées uniquement sur CET appareil, dans CE navigateur.</p><div class="notice">Aucun stock connu n'est préchargé : il serait trompeur d'afficher de fausses disponibilités. Toujours confirmer en magasin avant le déplacement.</div><form id="stockForm" class="formCard"><h3>Ajouter une vérification</h3><div class="row"><label class="field">Produit<input class="input" name="product" required maxlength="160" placeholder="UPC Noctali 30 ans"/></label><label class="field">Magasin<input class="input" name="store" required maxlength="100" placeholder="Fnac La Défense"/></label></div><div class="row"><label class="field">Statut<select name="state"><option>Inconnu</option><option>Disponible signalé</option><option>Indisponible signalé</option></select></label><label class="field">Prix (€) si connu<input class="input" name="price" inputmode="decimal" type="number" min="0" step="0.01" /></label></div><div class="row"><label class="field">Méthode<select name="method"><option>Page du magasin</option><option>Appel téléphonique</option><option>Retrait préparé</option><option>Observé en rayon</option></select></label><label class="field">Lien HTTPS (facultatif)<input class="input" name="url" type="url" placeholder="https://..."/></label></div><button class="btn" type="submit">Enregistrer sur mon téléphone</button></form><div class="top"><h3>Historique des vérifications</h3><button id="exportStocks" class="btn alt" type="button">Exporter JSON</button></div><div id="stockList" class="grid"></div></section>
<section id="calc" class="view"><h2>Calcul de marge</h2><p class="sub">Simulation simple par article, à partir de TES hypothèses. Aucun prix de revente n’est récupéré automatiquement.</p><div class="formCard"><div class="row"><label class="field">Prix d'achat (€)<input class="input" id="buy" type="number" min="0" step="0.01" value="60"/></label><label class="field">Livraison achat (€)<input class="input" id="shipping" type="number" min="0" step="0.01" value="5"/></label></div><div class="row"><label class="field">Revente supposée (€)<input class="input" id="sell" type="number" min="0" step="0.01" value="85"/></label><label class="field">Frais de vente (%)<input class="input" id="fees" type="number" min="0" max="100" step="0.5" value="5"/></label></div><div class="row"><label class="field">Autres frais (€)<input class="input" id="other" type="number" min="0" step="0.01" value="3"/></label></div><div class="metric"><span>Gain estimé par unité</span><strong id="gain">—</strong><small id="margin">—</small></div></div><div class="notice">À déduire en plus si applicable : impôts, retours, frais de trajet, stockage, risques d'invendus. Une estimation de prix affiché n'est pas une transaction réalisée.</div></section>
<footer>PokéRadar personnel, indépendant des marques. Dernière constitution des liens : 6 novembre 2026. Les liens peuvent devenir caducs. Le portail mobile est hors ligne ; l'application Mac gère la base et les scanners configurés.</footer>
</main><script>
'use strict';
const SOURCES=__SOURCES__;
const RAFFLES=__RAFFLES__;
const TRACKERS=__TRACKERS__;
let drawFilter='Tous',shopFilter='Toutes';
const $=id=>document.getElementById(id);
function element(tag,text,cls){let x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x;}
function anchor(text,href,secondary=false){let a=element('a',text,secondary?'btn alt':'btn');a.href=href;a.target='_blank';a.rel='noopener noreferrer';return a;}
function setView(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.go)));
function status(r){if(r.deadline && new Date(r.deadline)<=new Date())return 'Clos';if(r.state==='ouvert signalé' && r.deadline)return 'Ouvert signalé';if(r.state==='à surveiller')return 'À surveiller';return 'À vérifier';}
function pill(text){const cls=text==='Clos'?'red':text==='Ouvert signalé'?'green':'gold';return element('span',text,'tag '+cls);}
function makeFilters(holder,labels,current,onClick){holder.replaceChildren();labels.forEach(label=>{let b=element('button',label,'filter'+(label===current?' active':''));b.type='button';b.addEventListener('click',()=>onClick(label));holder.append(b);});}
function drawRender(){makeFilters($('drawFilters'),['Tous','Accès à l’achat','À surveiller','Concours pour gagner'],drawFilter,v=>{drawFilter=v;drawRender()});$('drawList').replaceChildren();let list=RAFFLES.filter(r=>drawFilter==='Tous'||r.category===drawFilter);list.sort((a,b)=>(['Accès à l’achat','À surveiller','Concours pour gagner'].indexOf(a.category)-['Accès à l’achat','À surveiller','Concours pour gagner'].indexOf(b.category)) || (({ 'Ouvert signalé':0,'À surveiller':1,'À vérifier':2,'Clos':3}[status(a)]??4)-({ 'Ouvert signalé':0,'À surveiller':1,'À vérifier':2,'Clos':3}[status(b)]??4))); list.forEach(r=>{let c=element('article',undefined,'card');let top=element('div',undefined,'top');top.append(element('h3',r.brand),pill(status(r)));c.append(top,element('h3',r.title),element('span',r.category+' · '+r.method,'tag'),element('p','Conditions : '+r.requirements));if(r.deadline)c.append(element('p','Date limite annoncée : '+new Intl.DateTimeFormat('fr-FR',{timeZone:'Europe/Paris',dateStyle:'medium',timeStyle:'short'}).format(new Date(r.deadline))));c.append(element('p',r.note));let links=element('div',undefined,'links');links.append(anchor('Ouvrir le lien',r.url));if(r.source&&r.source!==r.url)links.append(anchor('Source',r.source,true));c.append(links);$('drawList').append(c)});}
function searchUrl(s,q){let x=encodeURIComponent(q);if(s.strategy==='amazon')return 'https://www.amazon.fr/s?k='+x;if(s.strategy==='fnac')return 'https://www.fnac.com/SearchResult/ResultList.aspx?Search='+x;if(s.strategy==='ebay')return 'https://www.ebay.fr/sch/i.html?_nkw='+x;if(s.strategy==='cardmarket')return 'https://www.cardmarket.com/fr/Pokemon/Products/Search?searchString='+x;if(s.strategy==='vinted')return 'https://www.vinted.fr/catalog?search_text='+x;if(s.strategy==='leboncoin')return 'https://www.leboncoin.fr/recherche?text='+x;if(s.strategy==='category')return s.site;return 'https://www.google.com/search?q='+encodeURIComponent('site:'+s.domain+' '+q);}
function shopRender(){let groups=['Toutes',...new Set(SOURCES.map(s=>s.group))];makeFilters($('shopFilters'),groups,shopFilter,v=>{shopFilter=v;shopRender()});$('shopList').replaceChildren();let q=$('productQuery').value.trim().slice(0,160);SOURCES.filter(s=>shopFilter==='Toutes'||s.group===shopFilter).forEach(s=>{let c=element('article',undefined,'card');let top=element('div',undefined,'top');top.append(element('h3',s.name),element('span',s.group,'tag'));c.append(top,element('p',s.warning||'Vérifier vendeur, prix et disponibilité.'));let links=element('div',undefined,'links');if(q)links.append(anchor('Chercher',searchUrl(s,q)));links.append(anchor('Boutique',s.site,true));if(s.local)links.append(anchor('Près de Suresnes','https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(s.name+' près de Suresnes'),true));c.append(links);$('shopList').append(c);});}
$('productQuery').addEventListener('input',shopRender);
const KEY='pokeradar_mobile_stocks_v04';let stocks=[];try{const saved=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(saved))stocks=saved.slice(0,500);}catch(_){stocks=[];}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(stocks));}catch(_){alert('Enregistrement indisponible dans ce navigateur. Exporte tes données en JSON.');}}
function validateUrl(u){if(!u)return true;try{let parsed=new URL(u);return parsed.protocol==='https:' && !!parsed.hostname;}catch(_){return false}}
$('stockForm').addEventListener('submit',ev=>{ev.preventDefault();const fd=new FormData(ev.currentTarget);let url=String(fd.get('url')||'').trim();if(!validateUrl(url)){alert('Le lien doit commencer par https://');return;}let price=String(fd.get('price')||'');if(price&&(!Number.isFinite(Number(price))||Number(price)<0)){alert('Prix invalide');return;}stocks.unshift({id:(typeof crypto!=='undefined' && crypto.randomUUID ? crypto.randomUUID() : String(Date.now())+'-'+Math.random()),product:String(fd.get('product')).trim().slice(0,160),store:String(fd.get('store')).trim().slice(0,100),state:String(fd.get('state')),price:price?Number(price):null,method:String(fd.get('method')),url,checked:new Date().toISOString()});stocks=stocks.slice(0,500);persist();ev.currentTarget.reset();stockRender();});
function stockRender(){let avail=stocks.filter(x=>x.state==='Disponible signalé').length;$('metricStock').textContent=String(stocks.length);$('stockList').replaceChildren();if(!stocks.length){$('stockList').append(element('div','Aucune disponibilité renseignée. Ajoute ta première vérification ci-dessus.','empty'));return;}stocks.forEach(r=>{let c=element('article',undefined,'card');let top=element('div',undefined,'top');top.append(element('h3',r.product),pill(r.state==='Disponible signalé'?'À revérifier':r.state==='Indisponible signalé'?'Clos':'À vérifier'));c.append(top,element('h3',r.store),element('p','Dernière vérification : '+new Date(r.checked).toLocaleString('fr-FR')),element('p',r.method+(r.price!==null?' · '+r.price.toFixed(2)+' €':'')));let links=element('div',undefined,'links');if(r.url&&validateUrl(r.url))links.append(anchor('Fiche produit',r.url));let del=element('button','Supprimer','btn danger');del.type='button';del.addEventListener('click',()=>{if(confirm('Supprimer cette observation ?')){stocks=stocks.filter(x=>x.id!==r.id);persist();stockRender();}});links.append(del);c.append(links);$('stockList').append(c);});}
$('exportStocks').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(stocks,null,2)],{type:'application/json'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pokeradar_stocks_mobile.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});
function calc(){const nums=['buy','shipping','sell','fees','other'].map(id=>Number($(id).value));if(nums.some(n=>!Number.isFinite(n)||n<0)||nums[3]>100){$('gain').textContent='Saisie invalide';$('margin').textContent='';return;}const [buy,shipping,sell,fees,other]=nums;let cost=buy+shipping;let gain=sell*(1-fees/100)-cost-other;$('gain').textContent=gain.toLocaleString('fr-FR',{style:'currency',currency:'EUR'});$('margin').textContent=cost>0?'Marge sur coût total : '+(gain/cost*100).toFixed(1)+' %':'Coût d’achat non renseigné';}
['buy','shipping','sell','fees','other'].forEach(id=>$(id).addEventListener('input',calc));
TRACKERS.forEach(t=>{let c=element('article',undefined,'card');c.append(element('h3',t[0]),element('p',t[2]));let links=element('div',undefined,'links');links.append(anchor('Consulter',t[1]));c.append(links);$('trackers').append(c);});
$('metricShop').textContent=SOURCES.length;$('metricRaffles').textContent=RAFFLES.length;drawRender();shopRender();stockRender();calc();
</script></body></html>'''
    return page.replace('__SOURCES__',source_json).replace('__RAFFLES__',raffle_json).replace('__TRACKERS__',trackers_json)


def main():
    output=ROOT/'pokeradar_portail_mobile_v04.html'
    output.write_text(build_html(),encoding='utf-8')
    print(output)

if __name__=='__main__':
    main()
